    {"q":"합성함수에서 $f \\circ g = g \\circ f$ 가 항상 성립한다.","t":"ox","a":1,"why":"순서를 바꾸면 결과가 달라지는 게 보통이에요."},
    {"q":"$(f \\circ g)(x)$ 의 뜻은?","t":"mc","o":["$f(g(x))$","$g(f(x))$","$f(x)g(x)$","$f(x)+g(x)$"],"a":0,"why":"안쪽부터 계산해요."},
    {"q":"$f^{-1}(f(x)) = x$ 이다. (역함수가 존재할 때)","t":"ox","a":0,"why":"되돌아오는 것이 역함수의 정의예요."},
    {"q":"$y = \\sqrt{x}$ 의 그래프는 $y = x^2\\ (x \\ge 0)$ 의 그래프와 어떤 관계인가?","t":"mc","o":["직선 $y=x$ 에 대해 대칭","$x$축에 대해 대칭","$y$축에 대해 대칭","겹친다"],"a":0,"why":"서로 역함수예요."},
    {"q":"1부터 9까지의 숫자로 중복 없이 세 자리 수를 만드는 경우의 수는?","t":"mc","o":["$9 \\times 8 \\times 7$","$9^3$","$_9\\mathrm{C}_3$","$3!$"],"a":0,"why":"자리마다 쓸 수 있는 숫자가 하나씩 줄어요."},
    {"q":"서로 다른 $n$개를 원형으로 배열하는 경우의 수는 $(n-1)!$ 이다.","t":"ox","a":0,"why":"회전해서 같아지는 것을 하나로 세기 때문이에요."},
    {"q":"$_5\\mathrm{C}_2$ 의 값은?","t":"mc","o":["$10$","$20$","$5$","$25$"],"a":0,"why":"$\\dfrac{5 \\times 4}{2 \\times 1}$ 이에요."},
    {"q":"$_n\\mathrm{C}_0 = 1$ 이다.","t":"ox","a":0,"why":"아무것도 안 뽑는 방법이 한 가지라고 약속했어요."},
    {"q":"단위행렬 $E$ 가 하는 역할은?","t":"mc","o":["곱셈에서 1과 같은 역할","덧셈에서 0과 같은 역할","행렬을 뒤집는다","행렬을 없앤다"],"a":0,"why":"$AE = EA = A$ 예요."},
    {"q":"모든 정사각행렬은 역행렬을 갖는다.","t":"ox","a":1,"why":"행렬식이 0이면 역행렬이 없어요."},
    {"q":"$2 \\times 2$ 행렬 $\\begin{pmatrix} a & b \\\\ c & d \\end{pmatrix}$ 의 역행렬이 존재할 조건은?","t":"mc","o":["$ad - bc \\ne 0$","$ad - bc = 0$","$a \\ne 0$","$ad = bc$"],"a":0,"why":"이 값을 행렬식이라고 불러요."}
